def compact(text):
    text = re.sub(r"\s+", " ", text).strip()
    text = re.sub(r"([\u0e31-\u0e4e])\1+", r"\1", text)
    replacements = {
        "น้้า": "น้ำ", "นํา": "น้ำ", "ไม": "ไม่", "ได": "ได้", "ขอใด": "ข้อใด",
        "ตอไป": "ต่อไป", "ตอ": "ต่อ", "ขาง": "ข้าง", "ขึน": "ขึ้น", "สวน": "ส่วน",
        "สงผล": "ส่งผล", "ปจจุบัน": "ปัจจุบัน", "บัจจุบัน": "ปัจจุบัน",
        "บัญหา": "ปัญหา", "ตอง": "ต้อง", "สําหรับ": "สำหรับ", "สําคัญ": "สำคัญ",
        "สํานวน": "สำนวน", "จํานวน": "จำนวน", "ทํา": "ทำ", "คํา": "คำ",
        "กําลัง": "กำลัง", "กําหนด": "กำหนด", "จําเป็น": "จำเป็น", "ดําเนิน": "ดำเนิน",
        "ตํารวจ": "ตำรวจ", "ตําแหน่ง": "ตำแหน่ง", "ลําดับ": "ลำดับ",
        "กระ ะ": "กระ", "ะจํา": "จำ", "ะทบ": "ทบ", " ะ": "ะ",
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    return re.sub(r"\s+([,.)])", r"\1", text).strip(" ·-")


def question_start(lines, page, number):
    if (page, number) in MANUAL_STARTS:
        return MANUAL_STARTS[(page, number)]
    pattern = re.compile(rf"^{number}\s*[.,)]?\s+")
    for index, line in enumerate(lines):
        if pattern.match(line):
            return index
    raise ValueError(f"Missing question start: page {page}, question {number}")


def option_marker(line):
    match = re.match(r"^([1-4])\s*[.,)]?\s+(.+)", line)
    return (int(match.group(1)), match.group(2)) if match else None


def parse_block(number, block):
    markers = []
    for index, line in enumerate(block):
        marker = option_marker(line)
        if marker:
            markers.append((index, *marker))
    # A valid set is a consecutive 1,2,3,4 run. Ignore numbers quoted inside passages.
    run = None
    for index in range(len(markers) - 3):
        if [item[1] for item in markers[index:index + 4]] == [1, 2, 3, 4]:
            run = markers[index:index + 4]
    if not run:
        return {"number": number, "block": block, "markers": markers}
    heading_end = run[0][0]
    prompt = compact(" ".join(block[:heading_end]))
    prompt = re.sub(rf"^[^ก-๙A-Za-z\"“]*{number}\s*[.,)]?\s*", "", prompt).strip()
    choices = []
    for offset, (line_index, _, first) in enumerate(run):
        end = run[offset + 1][0] if offset < 3 else len(block)
        choices.append(compact(" ".join([first, *block[line_index + 1:end]])))
    return {"number": number, "question": prompt, "choices": choices}


